public class Main {
    static long solveCase(int m, int[] vals) {
        Arrays.sort(vals);
        long teamA = 0, teamB = 0;
        boolean aTurn = true;
        for (int i = m - 1; i >= 0; i--) {
            if (aTurn) teamA += vals[i];
            else teamB += vals[i];
            aTurn = !aTurn;
        }
        return teamA - teamB;
    }

