import sys

def solve_case(m, v):
    # 降序排序
    v.sort(reverse=True)
    pioneer = 0
    strategist = 0
    for i in range(m):
        if i % 2 == 0:
            pioneer += v[i]      # 先锋取奇数位（0-based 偶数）
        else:
            strategist += v[i]   # 谋士取偶数位（0-based 奇数）
    return pioneer - strategist

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    idx = 1
    out = []
    for _ in range(t):
        m = data[idx]
        idx += 1
        v = data[idx:idx + m]
        idx += m
        out.append(str(solve_case(m, v)))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
```

